package com.aditya.chat.service; import com.aditya.chat.dto.MessageRequest; import com.aditya.chat.entity.ChatMessage; import com.aditya.chat.repository.MessageRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; @Service public class MessageService{final MessageRepository repo;public MessageService(MessageRepository r){repo=r;}public ChatMessage save(String sender,MessageRequest r){return repo.save(new ChatMessage(r.chatId(),sender,r.content()));}public Page<ChatMessage> history(String chatId,int page,int size){return repo.findByChatIdOrderByCreatedAtDesc(chatId,PageRequest.of(Math.max(0,page),Math.min(Math.max(1,size),100)));}}
